import math

def _build_agent_impl(sandbox):
    beams = []

    # Source guiding beams (raised y, steeper angle for forward guidance)
    for i in range(3):
        x = 6.0 + i * 1.0
        y = 1.0 + i * 0.5  # Raising y to avoid gravity well
        b = sandbox.add_beam(x, y, 1.1, 0.2, angle=0.7, density=50.0)  # Steeper angle for forward push
        sandbox.add_joint(b, None, (x, 0.0), type='rigid')  # Anchor to ground
        beams.append(b)

    # Gravity well bypass beams (placed above gravity well with optimized angle)
    for i in range(4):
        x = 10.0 + i * 2.0
        y = 4.0  # Above gravity well (y=3.5) with buffer
        b = sandbox.add_beam(x, y, 1.1, 0.2, angle=1.0, density=50.0)  # Optimized upward angle
        sandbox.add_joint(b, None, (x, 0.0), type='rigid')  # Anchor to ground
        beams.append(b)

    # Headwind zone support beams (horizontal orientation for forward momentum)
    for i in range(3):
        x = 14.0 + i * 2.0
        y = 4.0  # Above headwind zone
        b = sandbox.add_beam(x, y, 1.1, 0.2, angle=0.2, density=50.0)  # Horizontal orientation
        sandbox.add_joint(b, None, (x, 0.0), type='rigid')  # Anchor to ground
        beams.append(b)

    # Target guiding beams (lower y, gentler downward angle for target alignment)
    for i in range(3):
        x = 16.0 + i * 1.0  # Within build zone
        y = 3.5  # Lower y for better target alignment
        b = sandbox.add_beam(x, y, 1.1, 0.2, angle=-0.3, density=50.0)  # Gentler downward angle
        sandbox.add_joint(b, None, (x, 0.0), type='rigid')  # Anchor to ground
        beams.append(b)

    # Verify mass budget
    total_mass = sandbox.get_structure_mass()
    if total_mass > 380:
        raise ValueError(f"Structure mass {total_mass} kg exceeds budget")

    return beams[0]

